local MournMainDialog = Class("MournMainDialog")
local ActivityMournUtils = import('Game.Activity.Mourn.ActivityMournUtils')
function MournMainDialog:__init()

end

function MournMainDialog:__delete()
	self.controller = nil
end

function MournMainDialog:Awake()
	self:AddUIClick()
end

function MournMainDialog:AddUIClick()
	SetButtonAction(self.BtnBoss,Bind(self,self.OnBtnBossClick))
	SetButtonAction(self.BtnTower,Bind(self,self.OnBtnTowerClick))
	SetButtonAction(self.BtnStory,Bind(self,self.OnBtnStoryClick))
	SetButtonAction(self.BtnGachapon,Bind(self,self.OnBtnGachaponClick))
	SetButtonAction(self.BtnPlay,Bind(self,self.OnBtnPlayClick))
	SetButtonAction(self.BtnExplain,Bind(self,self.OnBtnExplainClick))
end

function MournMainDialog:OnFocus(focus)
	if focus then
	
	end
end

function MournMainDialog:OnShow()

end

function MournMainDialog:OnInitialize()
	self.activityData = ActivityMournUtils.GetActivityData()
	GameUtils.Request(Interfaces.ActivityTowerChangeHome,{activityUuid = self.activityData.id},function(request,response)
		if checkNumber(response.errCode) == 0 then
			ActivityMournUtils.GetMournMgr():InitialDojo(response.data)
			local isPlayChapter = checkNumber(CfUtils.GetLocalData("MournMainDialogChapter",0)) == 1
			if not isPlayChapter then
				self:OnBtnPlayClick()
			end
			self:Refresh()
			local currency = ActivityMournUtils.GetShowCurrency()
			if table.count(currency) > 0 then
				CfUtils.RefreshTopGoods(currency)
			end
		end
	end)
end

function MournMainDialog:OnFinalize()
	self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
	self:Delete()
	self = nil --lua层的gc需要
end

function MournMainDialog:Refresh()
	self:SetTimeShow()
	self:RefreshBossBtnState()
	ActivityMournUtils.PlayBgm()
end

function MournMainDialog:RefreshBossBtnState()
	local isUnLock = ActivityMournUtils.IsBossUnLock()
	CfUtils.SetUISwitchImage(self.Imgboss,isUnLock and 1 or 2)
end

function MournMainDialog:SetTimeShow()
	--region 时间
	local startTime =  self.activityData.startTime
	local closeTime =  self.activityData.closeTime
	local ActivityUtils         = import("Game.Activity.ActivityUtils")
	CfUtils.FillText(self.TextTime, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
end

---click start-------------------------------
function MournMainDialog:OnBtnBossClick()
	local isUnLock = ActivityMournUtils.IsBossUnLock()
	if isUnLock then
		CfUtils.DialogOpen(Constants.UITypeIds.MournBossDialog,nil, { { id = Constants.UITypeIds.MournMainDialog } })
	else
		GameUtils.Toast(localize("通关厄运倒带50层后开启"))
	end
end

function MournMainDialog:OnBtnTowerClick()
	CfUtils.DialogOpen(Constants.UITypeIds.MournTowerDialog,nil, { { id = Constants.UITypeIds.MournMainDialog } })
end

function MournMainDialog:OnBtnStoryClick()
	CfUtils.DialogOpen(Constants.UITypeIds.MournChapterEntryDialog,nil, { { id = Constants.UITypeIds.MournMainDialog } })
end

function MournMainDialog:OnBtnGachaponClick()
	local gachaponUtils = import('Game.Gachapon.GachaponUtils')
	local scheduleVo = ActivityMournUtils.GetSchConfig()
	gachaponUtils.OpenGachapon({jumpPool = scheduleVo.poolId}, { { id = Constants.UITypeIds.MournMainDialog } })
end

function MournMainDialog:OnBtnPlayClick()
	local scheduleVo = ActivityMournUtils.GetSchConfig()
	local ChapterUtils = import('Game.Chapter.ChapterUtils')
	local URPCameraController =  CS.Game.Native.URP.URPCameraController.Instance
	ChapterUtils.ProcessChapter(checkNumber(scheduleVo.storyId), function(go)
		self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
		URPCameraController:SetMainCameraActive(false)
		self._plotGo = go
	end, function()
		self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
		URPCameraController:SetMainCameraActive(true)
		CfUtils.WriteLocalData("MournMainDialogChapter",1)
		CfUtils.SafeDelete(self._plotGo)
	end)
end

function MournMainDialog:OnBtnExplainClick()
	local ruleId = ActivityMournUtils.GetRuleId()
	if checkNumber(ruleId) > 0 then
		CfUtils.ShowModuleToast(ruleId)
	end
end
---click end----------------------------------
return MournMainDialog